const http = require('http');
const crypto = require('crypto');
const url = require('url');

const SECRET = process.env.AUTH_SECRET;
if (!SECRET || SECRET.length < 32) {
  throw new Error('AUTH_SECRET must be at least 32 characters');
}

// Secure password storage with scrypt
const users = new Map();

async function hashPassword(password) {
  const salt = crypto.randomBytes(16).toString('hex');
  const derived = await new Promise((resolve, reject) => {
    crypto.scrypt(password, salt, 64, (err, key) => {
      if (err) reject(err);
      else resolve(key.toString('hex'));
    });
  });
  return `${salt}:${derived}`;
}

async function verifyPassword(password, stored) {
  const [salt, hash] = stored.split(':');
  const derived = await new Promise((resolve, reject) => {
    crypto.scrypt(password, salt, 64, (err, key) => {
      if (err) reject(err);
      else resolve(key.toString('hex'));
    });
  });
  const hashBuf = Buffer.from(hash, 'hex');
  const derivedBuf = Buffer.from(derived, 'hex');
  if (hashBuf.length !== derivedBuf.length) return false;
  return crypto.timingSafeEqual(hashBuf, derivedBuf);
}

// Rate limiting to prevent brute force
const loginAttempts = new Map();

function getRateLimitDelay(identifier) {
  const attempts = loginAttempts.get(identifier) || { count: 0, lastAttempt: 0 };
  const now = Date.now();
  // Reset after 15 minutes
  if (now - attempts.lastAttempt > 900000) {
    attempts.count = 0;
  }
  attempts.count++;
  attempts.lastAttempt = now;
  loginAttempts.set(identifier, attempts);
  // Exponential backoff: 0, 100, 200, 400, 800, 1600ms...
  if (attempts.count <= 1) return 0;
  return Math.min(100 * Math.pow(2, attempts.count - 2), 30000);
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// Dummy scrypt computation to normalize timing for non-existent users
async function dummyVerify(password) {
  const dummySalt = '0'.repeat(32);
  const dummyHash = '0'.repeat(128);
  await new Promise((resolve, reject) => {
    crypto.scrypt(password, dummySalt, 64, (err, key) => {
      if (err) reject(err);
      else resolve(key.toString('hex'));
    });
  });
  return false;
}

// Initialize demo users
async function initUsers() {
  users.set('admin', {
    passwordHash: await hashPassword(process.env.ADMIN_PASS || 'Str0ng!P@ssw0rd#2024'),
    role: 'admin',
    mfa: true
  });
  users.set('service-account', {
    passwordHash: await hashPassword(process.env.SVC_PASS || 'Sv(4cc0unt!S3cur3'),
    role: 'service',
