  });
}

async function handleLogin(req, res) {
  let body = '';
  const maxSize = 4096;

  for await (const chunk of req) {
    body += chunk;
    if (body.length > maxSize) {
      res.writeHead(413);
      res.end(JSON.stringify({ error: 'Request too large' }));
      return;
    }
  }

  let parsed;
  try {
    parsed = JSON.parse(body);
  } catch {
    res.writeHead(400);
    res.end(JSON.stringify({ error: 'Invalid JSON' }));
    return;
  }

  const { username, password } = parsed;
  if (typeof username !== 'string' || typeof password !== 'string') {
    res.writeHead(400);
    res.end(JSON.stringify({ error: 'Invalid credentials format' }));
    return;
  }

  if (username.length > 128 || password.length > 256) {
    res.writeHead(400);
    res.end(JSON.stringify({ error: 'Input too long' }));
    return;
  }

  // Apply rate limiting based on IP + username to prevent brute force
  // Rate limit is applied BEFORE user lookup to avoid timing oracle
  const clientIp = req.socket.remoteAddress || 'unknown';
  const rateLimitKey = `${clientIp}:${username}`;
  const delay = getRateLimitDelay(rateLimitKey);
  if (delay > 0) {
    await sleep(delay);
  }

  const user = users.get(username);
  let valid = false;

  if (user) {
    valid = await verifyPassword(password, user.passwordHash);
  } else {
    // Perform dummy computation to normalize timing
    await dummyVerify(password);
  }

  if (valid) {
    const token = generateToken(username, user.role);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ token, expiresIn: 3600 }));
    return;
  }

  // Generic error for both invalid user and invalid password
  res.writeHead(401, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Invalid credentials' }));
}

function generateToken(username, role) {
  const header = Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })).toString('base64url');
  const payload = Buffer.from(JSON.stringify({
    sub: username,
    role: role,
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(Date.now() / 1000) + 3600
  })).toString('base64url');
  const signature = crypto.createHmac('sha256', SECRET)
    .update(`${header}.${payload}`)
    .digest('base64url');
  return `${header}.${payload}.${signature}`;
}

function verifyToken(token) {
  if (typeof token !== 'string') return null;
  const parts = token.split('.');
  if (parts.length !== 3) return null;

  const [header, payload, signature] = parts;
  const expected = crypto.createHmac('sha256', SECRET)
    .update(`${header}.${payload}`)
    .digest('base64url');

  const sigBuf = Buffer.from(signature, 'base64url');
  const expBuf = Buffer.from(expected, 'base64url');
  if (sigBuf.length !== expBuf.length) return null;
  if (!crypto.timingSafeEqual(sigBuf, expBuf)) return null;

  try {
    const data = JSON.parse(Buffer.from(payload, 'base64url').toString());
    if (!data.sub || !data.role || !data.exp) return null;
    if (typeof data.exp !== 'number' || data.exp < Math.floor(Date.now() / 1000)) return null;
    return data;
  } catch {
    return null;
  }
}

async function handleProtected(req, res) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.writeHead(401);
    res.end(JSON.stringify({ error: 'Missing authorization' }));
    return;
  }

  const token = authHeader.slice(7);
  const payload = verifyToken(token);
  if (!payload) {
    res.writeHead(401);
    res.end(JSON.stringify({ error: 'Invalid or expired token' }));
    return;
  }

  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ message: `Hello ${payload.sub}`, role: payload.role }));
}

const server = http.createServer(async (req, res) => {
  const parsedUrl = url.parse(req.url, true);

  try {
    if (req.method === 'POST' && parsedUrl.pathname === '/auth/login') {
      await handleLogin(req, res);
    } else if (req.method === 'GET' && parsedUrl.pathname === '/api/protected') {
      await handleProtected(req, res);
    } else {
      res.writeHead(404);
      res.end(JSON.stringify({ error: 'Not found' }));
    }
  } catch (err) {
    res.writeHead(500);
    res.end(JSON.stringify({ error: 'Internal server error' }));
  }
});

initUsers().then(() => {
  server.listen(process.env.PORT || 3000);
});
